import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷二·27","description":"易小帖 - 卷二·27","frontmatter":{"title":"卷二·27","description":"易小帖 - 卷二·27"},"headers":[],"relativePath":"zh/classics/yixiaotie/067.md","filePath":"zh/classics/yixiaotie/067.md"}'),o={name:"zh/classics/yixiaotie/067.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷二·27",tabindex:"-1"},[r("卷二·27 "),e("a",{class:"header-anchor",href:"#卷二·27","aria-label":"Permalink to “卷二·27”"},"​")],-1),e("p",null,"連山歸藏二易久亡，按《北史》劉弘奏購求天下遺書，其時劉炫頗有名遂，造偽連山易、魯史記等百餘捲，上之，已取賞，去而後有訟之者，免死除名。鄭樵謂：連山易至唐始出，皆偽書也。《崇文總目》載歸藏易晉太尉參軍薛貞註，在隋世尚存十三捲，後祗存《初經》、《齊母》、《本蓍》三篇，至唐世又有司馬膺註十三捲，至宋亦亡。晁以道謂：商易為張天覺偽作。或雲：即司馬膺作。故吳澄謂：連山歸藏，劉光伯、司馬膺偽書也。若衛元嵩作《元包》亦以先天后天太少陰陽立卦，一如乾寶所言，為宋人竊襲偽造之始。然亦冒名歸藏易，以坤先乾，此則倚傍不足道者。第桓譚《新論》雲：「連山八萬言，歸藏四千三百言。連山藏於蘭台，歸藏藏於太卜。」則必漢時尚見其書，故字數鑿鑿如此，惜不可考矣。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
